package com.harsh.explore.examples;import com.harsh.explore.data.Student;import java.util.Arrays;import java.util.function.Supplier;// The supplier interface is a functional interface that represents a supplier of results.// It has a single abstract method get() that returns a value.// It is often used in scenarios where you want to generate or provide a value without taking any input.// For example, you can use a Supplier to create a new instance of a class or to provide a default value.// In this example, we will create a Supplier that generates a Student object.public class SupplierExample {    public static void main(String[] args) {        Supplier<Student> studentSupplier = () -> {            return new Student("Rameshwara", 2, 3.5, "Male",                    Arrays.asList("Cricket", "swimming", "badminton", "football"));        };        System.out.println("Name of the student is: " + studentSupplier.get().getName());    }}